struct Money: Hashable, Sendable {
    let amountCents: Int
    let currency: Currency

    init(amountCents: Int, currency: Currency) throws {
        guard amountCents >= 0 else { throw MoneyError.negativeAmount }
        (self.amountCents, self.currency) = (amountCents, currency)
    }
}
